La corretta validazione numerica dei dati non garantisce l'assenza di bias statistici o limiti sistematici insiti nelle modalità di campionamento.

Per assicurare la verificabilità forense e la responsabilità algoritmica, ogni dataset destinato all'addestramento deve essere corredato da una scheda di documentazione standardizzata, conforme alle linee guida del [Google Data Cards Playbook](https://developers.google.com/learn/pathways/data-cards-playbook) (il framework metodologico ideato da [Google](https://about.google/) per la trasparenza e la documentazione sistematica dei dataset). La Data Card formalizza la provenienza delle fonti, l'intervallo temporale di acquisizione, le limitazioni note, le popolazioni sottorappresentate e i casi d'uso esplicitamente vietati.

```python
import json

data_card_schema = {
    "metadata": {
        "dataset_name": "Cyber_Threat_Events_Corpus",
        "version": "1.2.0",
        "maintainer": "Security Operations Center Analytics Team",
        "license": "CC-BY-4.0",
        "last_updated": "2026-08-18"
    },
    "provenance": {
        "source": "Network firewall gateway logs and honeytoken telemetry",
        "collection_method": "Automated ingestion via Kafka stream broker",
        "time_span": "2025-01-01 to 2025-12-31"
    },
    "schema_definition": {
        "id_sessione": {"type": "string", "description": "Identificativo pseudonimizzato della sessione TCP"},
        "tempo_risposta_ms": {"type": "float32", "description": "Latenza di risposta in millisecondi"},
        "codice_stato": {"type": "int32", "description": "Codice HTTP di terminazione connessione"}
    },
    "ethical_and_bias_considerations": {
        "represented_population": "Internal enterprise corporate infrastructure",
        "known_limitations": "Under-represents UDP anomalies and encrypted micro-tunnels",
        "prohibited_use_cases": "Automated attribution of physical identities without manual forensics"
    }
}

print(json.dumps(data_card_schema, indent=2))
```

Questo secondo laboratorio dimostra il Fattore 4: i tool non sono magia, sono output strutturati. Il modello genera un JSON che descrive quale funzione chiamare e con quali argomenti; il codice deterministico esegue la funzione e restituisce il risultato.

```python
"""
lab_tool_calling.py
Dimostra il pattern del 12-Factor Agent #4: Tools are Structured Outputs.
Simula un agente che emette JSON per le chiamate di tool,
con il codice deterministico che possiede il flusso di controllo (Fattore 9).
"""
import json

# --- Registro dei tool disponibili (l'applicazione li possiede) ---
TOOL_REGISTRY = {}

def register_tool(name: str):
    """Decoratore per registrare tool nel registro deterministico."""
    def decorator(func):
        TOOL_REGISTRY[name] = func
        return func
    return decorator

@register_tool("search_knowledge_base")
def search_kb(query: str, max_results: int = 5) -> dict:
    """Simula una ricerca nella Knowledge Base locale."""
    return {
        "results": [
            {"file": "D10-rag-knowledge-osint.md", "score": 0.92},
            {"file": "D12-agentic-mcp.md", "score": 0.87}
        ],
        "total": 2
    }

@register_tool("write_file")
def write_file(path: str, content: str) -> dict:
    """Simula la scrittura di un file (con validazione dei permessi)."""
    # Fattore 9: il codice deterministico valida PRIMA di eseguire
    forbidden_paths = ["/etc/", "/sys/", "C:\\Windows\\"]
    if any(path.startswith(p) for p in forbidden_paths):
        return {"error": "Permission denied", "path": path}
    return {"status": "written", "path": path, "bytes": len(content)}

def execute_tool_call(tool_call: dict) -> dict:
    """
    Esegue una chiamata di tool emessa dal modello.
    Il modello produce il JSON, l'applicazione lo esegue deterministicamente.
    """
    name = tool_call.get("tool")
    args = tool_call.get("arguments", {})

    if name not in TOOL_REGISTRY:
        # Fattore 5: errore compattato, non traceback completo
        return {"error": f"Tool '{name}' not found", "available": list(TOOL_REGISTRY.keys())}

    try:
        result = TOOL_REGISTRY[name](**args)
        return {"status": "success", "result": result}
    except TypeError as e:
        return {"error": f"Invalid arguments: {str(e)[:100]}"}

# --- Simulazione ---
if __name__ == "__main__":
    # Simula l'output del modello: un JSON strutturato, non testo libero
    model_outputs = [
        {"tool": "search_knowledge_base",
         "arguments": {"query": "come funziona l'hybrid search", "max_results": 3}},
        {"tool": "write_file",
         "arguments": {"path": "output/report.md",
                        "content": "# Report\n\nAnalisi completata."}},
        {"tool": "delete_database",
         "arguments": {"target": "production"}}
    ]

    print("=== Loop Agente con Tool Calling Deterministico ===\n")

    # Fattore 9: il CODICE possiede il loop, non il modello
    MAX_ITERATIONS = 10
    budget_tokens = 50000
    tokens_used = 0

    for i, tool_call in enumerate(model_outputs):
        if i >= MAX_ITERATIONS:
            print(f"STOP: raggiunto il limite di {MAX_ITERATIONS} iterazioni")
            break

        tokens_used += 500  # stima semplificata
        if tokens_used > budget_tokens:
            print(f"STOP: budget token esaurito ({tokens_used}/{budget_tokens})")
            break

        print(f"Iterazione {i+1}: tool={tool_call['tool']}")
        result = execute_tool_call(tool_call)
        print(f"  Risultato: {json.dumps(result, indent=2, ensure_ascii=False)}\n")
```

Il laboratorio mostra tre aspetti cruciali. Il modello non "chiama" i tool: emette JSON che il codice deterministico interpreta ed esegue. Il codice possiede i limiti (budget, iterazioni massime, permessi sui path). E quando il modello tenta di chiamare un tool inesistente (`delete_database`), l'errore viene compattato in un messaggio conciso che può essere iniettato nel contesto successivo per auto-correzione.

Questo laboratorio mostra come un'applicazione Client (es. DeepSeek Harness o Claude Desktop) configura la connessione ai propri Server MCP tramite un file JSON, definendo i percorsi eseguibili o gli URL di rete.

```json
{
  "mcpServers": {
    "filesystem_locale": {
      "command": "npx",
      "args": [
        "-y",
        "@modelcontextprotocol/server-filesystem",
        "C:\\Users\\Analyst\\Progetti\\Investigazioni",
        "C:\\Users\\Analyst\\Download"
      ]
    },
    "qdrant_hybrid_search": {
      "command": "python",
      "args": [
        "-m",
        "mcp_qdrant_hybrid",
        "--url",
        "http://localhost:6333",
        "--collection",
        "obsidian_vault"
      ]
    },
    "osint_sandbox": {
      "command": "docker",
      "args": [
        "exec",
        "-i",
        "osint_vm_container",
        "node",
        "/app/mcp-server-puppeteer/build/index.js"
      ]
    }
  }
}
```

La configurazione dimostra la potenza dell'architettura: il client delega l'accesso ai file locali a un pacchetto Node.js, la ricerca semantica a un modulo Python, e lo scraping web a un ambiente isolato Docker, coordinando il tutto come un'interfaccia unificata.

Questo laboratorio dimostra l'alberatura fisica (directory tree) e i file di configurazione essenziali per costruire un Agent Plugin compatibile con lo standard 2026. Il plugin ipotetico, `it.osint.registry`, dota l'agente delle competenze e del codice per interrogare i registri pubblici italiani.

```bash
# Alberatura del pacchetto Agent Plugin
it.osint.registry/
├── plugin.json             # Manifesto dello standard (Obbligatorio)
├── README.md               # Documentazione per l'utente umano
├── mcp.json                # Configurazione di avvio del server (Opzionale)
├── skills/                 # Directory delle competenze testuali
│   └── company_search.md   # Istruzioni in linguaggio naturale per l'agente
└── src/                    # Codice sorgente del server MCP
    ├── main.py
    └── requirements.txt
```

Il file `plugin.json` dichiara i metadati e mappa le risorse.

```json
{
  "$schema": "https://agent-plugins.org/draft-01/schema.json",
  "name": "it.osint.registry",
  "version": "1.0.0",
  "description": "Connettore MCP e Skill per l'interrogazione dei registri camerali italiani.",
  "authors": ["Analista OSINT <analista@example.com>"],
  "license": "MIT",
  "capabilities": {
    "mcpServers": {
      "registry_api": {
        "configPath": "./mcp.json"
      }
    },
    "skills": {
      "path": "./skills"
    }
  },
  "extensions": {
    "openwork": {
      "uiMode": "headless"
    }
  }
}
```

Il file `mcp.json` definisce come il client AI deve avviare il processo, esplicitando la richiesta di una variabile d'ambiente (la chiave API del registro).

```json
{
  "transport": "stdio",
  "command": "python",
  "args": ["src/main.py"],
  "env": {
    "REQUIRED": ["REGISTRO_API_KEY"]
  }
}
```

Questo secondo laboratorio implementa un validatore che controlla se un file `IDENTITY.md` contiene tutte le sezioni richieste dalla metodologia ICM e segnala le carenze.

```python
"""
lab_identity_validator.py
Valida un file IDENTITY.md verificando la presenza di tutte
le sezioni obbligatorie secondo la metodologia ICM.
"""
import pathlib, re, sys

REQUIRED_SECTIONS = {
    "ruolo": {
        "patterns": [r"##\s*ruolo", r"##\s*role", r"##\s*identit"],
        "description": "Definizione del ruolo e delle competenze"
    },
    "vincoli": {
        "patterns": [r"##\s*vincol", r"##\s*constraint", r"##\s*restrizioni"],
        "description": "Vincoli operativi (cosa NON deve fare)"
    },
    "input": {
        "patterns": [r"##\s*input", r"##\s*specifica.*input", r"##\s*file.*leggere"],
        "description": "Elenco dei file che l'agente deve leggere"
    },
    "output": {
        "patterns": [r"##\s*output", r"##\s*formato.*output", r"##\s*deliverable"],
        "description": "Formato e struttura del file di output"
    },
    "criteri": {
        "patterns": [r"##\s*criteri", r"##\s*success", r"##\s*completamento"],
        "description": "Criteri verificabili di completamento"
    },
    "tool": {
        "patterns": [r"##\s*tool", r"##\s*mcp", r"##\s*strumenti"],
        "description": "Permessi sui tool MCP autorizzati"
    }
}

def validate_identity(filepath: str) -> dict:
    """
    Valida un file IDENTITY.md e restituisce un report strutturato.
    """
    path = pathlib.Path(filepath)
    if not path.exists():
        return {"valid": False, "error": f"File non trovato: {filepath}"}

    content = path.read_text(encoding="utf-8").lower()
    report = {
        "filepath": str(path.resolve()),
        "total_lines": content.count("\n") + 1,
        "total_bytes": len(content),
        "sections_found": [],
        "sections_missing": [],
        "warnings": [],
        "valid": True
    }

    # Controlla ogni sezione obbligatoria
    for section_id, spec in REQUIRED_SECTIONS.items():
        found = any(
            re.search(pat, content, re.IGNORECASE)
            for pat in spec["patterns"]
        )
        if found:
            report["sections_found"].append(
                {"id": section_id, "description": spec["description"]}
            )
        else:
            report["sections_missing"].append(
                {"id": section_id, "description": spec["description"]}
            )
            report["valid"] = False

    # Warning: file troppo corto
    if report["total_lines"] < 20:
        report["warnings"].append(
            "Il file ha meno di 20 righe. Un IDENTITY.md completo "
            "dovrebbe avere almeno 30-50 righe."
        )

    # Warning: nessun vincolo negativo esplicito
    negative_markers = ["non deve", "non può", "vietato", "proibito",
                        "must not", "forbidden"]
    if not any(m in content for m in negative_markers):
        report["warnings"].append(
            "Nessun vincolo negativo esplicito trovato. "
            "Un IDENTITY.md robusto deve specificare cosa l'agente "
            "NON deve fare."
        )

    # Warning: nessun file di output specificato
    if "output" not in content or ".md" not in content:
        report["warnings"].append(
            "Non è specificato un nome file per l'output (es. output.md). "
            "L'agente non saprà dove salvare il risultato."
        )

    return report

def print_report(report: dict) -> None:
    """Stampa il report di validazione in formato leggibile."""
    status = "VALIDO" if report["valid"] else "NON VALIDO"
    print(f"\n{'='*60}")
    print(f"VALIDAZIONE IDENTITY.md — {status}")
    print(f"{'='*60}")
    print(f"File: {report.get('filepath', 'N/A')}")
    print(f"Righe: {report.get('total_lines', 0)} | "
          f"Byte: {report.get('total_bytes', 0)}")

    if report["sections_found"]:
        print(f"\n  Sezioni trovate ({len(report['sections_found'])}):")
        for s in report["sections_found"]:
            print(f"    [OK] {s['id']}: {s['description']}")

    if report["sections_missing"]:
        print(f"\n  Sezioni MANCANTI ({len(report['sections_missing'])}):")
        for s in report["sections_missing"]:
            print(f"    [!!] {s['id']}: {s['description']}")

    if report["warnings"]:
        print(f"\n  Avvertimenti ({len(report['warnings'])}):")
        for w in report["warnings"]:
            print(f"    [??] {w}")

    print(f"\n{'='*60}\n")

# --- Main ---
if __name__ == "__main__":
    if len(sys.argv) > 1:
        target = sys.argv[1]
    else:
        target = "demo_workspace/01_Ricerca/IDENTITY.md"
        print(f"Uso: python {sys.argv[0]} <percorso_identity.md>")
        print(f"Esempio con file di default: {target}\n")

    result = validate_identity(target)
    print_report(result)
```
